import React, { useState } from "react";
import Login from "./Login";
import Register from "./Register";

function App() {
  const [selectedFile, setSelectedFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [currentPage, setCurrentPage] = useState("main"); // "main", "login", "register"

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    if (file) {
      setSelectedFile(file);
      // Create preview URL
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
      setResults(null); // Clear previous results
    }
  };

  const analyzeFood = async () => {
    if (!selectedFile) {
      alert("Please select an image first!");
      return;
    }

    setLoading(true);
    const formData = new FormData();
    formData.append("file", selectedFile);

    try {
      const res = await fetch("http://127.0.0.1:8001/analyze_food/", {
        method: "POST",
        body: formData,
      });
      const data = await res.json();
      setResults(data);
    } catch (error) {
      console.error("Error analyzing food:", error);
      alert("Error analyzing image. Make sure the backend is running!");
    } finally {
      setLoading(false);
    }
  };

  const renderPage = () => {
    switch (currentPage) {
      case "login":
        return <Login onBack={() => setCurrentPage("main")} />;
      case "register":
        return <Register onBack={() => setCurrentPage("main")} />;
      default:
        return (
          <div className="min-h-screen bg-gradient-to-br from-orange-50 to-yellow-50 flex flex-col items-center justify-center p-6">
            <h1 className="text-4xl font-bold mb-2 text-orange-600">SmartChef 🍳</h1>
            <p className="text-gray-600 mb-6">AI-Powered Food Recognition & Nutrition Analysis</p>

            {/* Navigation buttons */}
            <div className="mb-8 flex gap-4">
              <button
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
                onClick={() => setCurrentPage("login")}
              >
                Login
              </button>
              <button
                className="px-6 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition"
                onClick={() => setCurrentPage("register")}
              >
                Register
              </button>
            </div>

            {/* Main content card */}
            <div className="bg-white rounded-xl shadow-2xl p-8 w-full max-w-2xl">
              {/* File upload section */}
              <div className="mb-6">
                <label className="block text-lg font-semibold mb-3 text-gray-700">
                  Upload Food Image 📸
                </label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileSelect}
                  className="w-full p-3 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-orange-400 transition"
                />
              </div>

              {/* Image preview */}
              {previewUrl && (
                <div className="mb-6">
                  <p className="text-sm font-semibold mb-2 text-gray-700">Preview:</p>
                  <img
                    src={previewUrl}
                    alt="Food preview"
                    className="w-full h-64 object-cover rounded-lg border-4 border-gray-200"
                  />
                </div>
              )}

              {/* Analyze button */}
              <button
                className={`w-full p-4 text-white rounded-lg font-semibold text-lg transition ${
                  loading
                    ? "bg-gray-400 cursor-not-allowed"
                    : "bg-green-600 hover:bg-green-700"
                }`}
                onClick={analyzeFood}
                disabled={loading || !selectedFile}
              >
                {loading ? "🔄 Analyzing..." : "🔍 Analyze Food"}
              </button>

              {/* Results section */}
              {results && results.status === "success" && (
                <div className="mt-6 p-6 bg-gradient-to-r from-green-50 to-blue-50 rounded-lg border border-green-200">
                  <h3 className="text-xl font-bold mb-4 text-green-700">✅ Analysis Results</h3>

                  {/* Detected ingredients */}
                  <div className="mb-4">
                    <p className="font-semibold text-gray-700 mb-2">🥗 Detected Ingredients:</p>
                    <div className="flex flex-wrap gap-2">
                      {results.ingredients.map((ingredient, index) => (
                        <span
                          key={index}
                          className="px-3 py-1 bg-white rounded-full text-sm font-medium text-gray-700 shadow"
                        >
                          {ingredient}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* Nutritional information */}
                  <div className="mt-4 p-4 bg-white rounded-lg">
                    <pre className="text-sm whitespace-pre-wrap font-mono text-gray-800">
                      {results.formatted_text}
                    </pre>
                  </div>
                </div>
              )}
            </div>
          </div>
        );
    }
  };

  return renderPage();
}

export default App;
